class Solution {
public:
    string reverseStr(string s, int k) {
        int n=s.size();
        if(n<=k)
        {
            reverse(s.begin(),s.end());
            return s;
        }
        for(int i=0;i<n;)
        {
            if(i+k<n)
                reverse(s.begin()+i,s.begin()+i+k);
            else
                reverse(s.begin()+i,s.end());
            i+=2*k;
        }
        return s;
    }
};

class Solution(object):
    def reverseStr(self, s, k):
        """
        :type s: str
        :type k: int
        :rtype: str
        """
        n = len(s)
        s_list = list(s)
        start = 0
        while True:
            p1, p2 = start, min(n - 1, start + k - 1)
            while p1 < p2:
                s_list[p1], s_list[p2] = s_list[p2], s_list[p1]
                p1 += 1
                p2 -= 1
            start = start + 2 * k
            if start > n - 1:
                break
        return "".join(s_list)
